<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Shared\Value\Validation;

use Respect\Validation\Validator;

final class RespectValidator
{
    public static function __callStatic(string $name, array $arguments)
    {
        if ($name === 'lengthBetween') {
            return self::base()::length($arguments[0] ?? null, $arguments[1] ?? null);
        }

        if ($name === 'lengthGreaterThanOrEqual') {
            return self::base()::length($arguments[0] ?? null, null);
        }

        if ($name === 'lengthLessThanOrEqual') {
            return self::base()::length(null, $arguments[0] ?? null);
        }

        if ($name === 'greaterThanOrEqual') {
            return self::base()::min($arguments[0] ?? null);
        }

        if ($name === 'lessThanOrEqual') {
            return self::base()::max($arguments[0] ?? null);
        }

        return self::base()::{$name}(...$arguments);
    }

    private static function base(): string
    {
        if (class_exists('Respect\\Validation\\ValidatorBuilder')) {
            return 'Respect\\Validation\\ValidatorBuilder';
        }

        return Validator::class;
    }
}
